$ts=date(DATE_ATOM);$dir='C:/laragon/www/yayasan-app/storage/app/audits/midtrans/'.date('Ymd_His').'-implementation-design';mkdir($dir,0777,true);
$design=['generated_at'=>$ts,'scope'=>'Design only; no package installation, source/database/config changes, or gateway calls','package'=>['name'=>'midtrans/midtrans-php','purpose'=>'Official PHP SDK for Snap token and transaction status API','install'=>'composer require midtrans/midtrans-php --no-interaction','status'=>'Proposal only; not installed'],'architecture'=>['service'=>'App\\Services\\Payments\\MidtransGatewayService','responsibilities'=>['createSnapToken from server-owned invoice amount','build unique order id','verify notification signature','map gateway status','fetch transaction status for reconciliation'],'controller'=>'Dedicated checkout and webhook controllers; controllers delegate business logic to service','legacy_boundary'=>'Never read or update legacy payment rows during new checkout; only use active PaymentInvoice and create PaymentTransaction rows'],'routes'=>['POST /payments/{invoice}/checkout'=>'auth + user authorization + throttle; returns Snap token','POST /payments/midtrans/webhook'=>'public gateway endpoint; no session auth; signed payload required','GET /payments/{transaction}/status'=>'auth + owner/admin authorization; reads local transaction status'],'webhook'=>['signature'=>'SHA512(order_id + status_code + gross_amount + server_key), constant-time comparison','idempotency'=>'Lookup gateway_order_id; lock transaction row; apply only valid state transition; repeated identical notifications return 200 without duplicate row','retries'=>'Return 2xx after durable processing; return 5xx only for retryable internal failure; log correlation id'],'order_id'=>['format'=>'SIDIKMA-{invoice_id}-{ULID}', 'storage'=>'string gateway_order_id','uniqueness'=>'unique database constraint for new gateway transactions after preflight; never reuse legacy order_id','amount_binding'=>'order amount stored locally and compared against webhook gross_amount'],'validation'=>['invoice'=>'exists, active, owned by current user or authorized admin, not already paid, not quarantined','user'=>'invoice owner active and authorized','amount'=>'read from payment_invoices server-side; positive decimal; never trust browser amount','status'=>'only unpaid/pending eligible for checkout; paid/failed policy explicit','currency'=>'IDR and integer rupiah amount sent to gateway'],'status_mapping'=>['capture'=>'paid','settlement'=>'paid','pending'=>'pending','authorize'=>'pending','deny'=>'failed','cancel'=>'failed','expire'=>'failed','failure'=>'failed','refund'=>'failed','chargeback'=>'failed'],'duplicate_prevention'=>['unique gateway_order_id','one active pending transaction per invoice/user according to business policy','database transaction around local pending row creation','idempotency key from order id and webhook event','never create transaction from callback if invoice/order cannot be verified'],'logging'=>['log order id, invoice id, transaction id, event/status, correlation id, result','mask email/phone where possible','never log server key, client key, authorization header, full webhook secret, or raw credentials','store sanitized payload snapshot only if policy permits'],'environments'=>['sandbox'=>'MIDTRANS_IS_PRODUCTION=false, sandbox server/client keys, sandbox API URL, separate webhook URL','production'=>'separate production keys and webhook URL, explicit deployment approval, secret manager/environment only','guard'=>'fail closed if environment/key mismatch; show no secret in UI/logs'],'authorization'=>['checkout'=>'invoice owner or permissioned admin only','webhook'=>'signature verification, no user session required','status/read'=>'owner, foundation admin, or policy-authorized role','admin'=>'manual reconciliation requires explicit permission and audit log'],'testing'=>['unit'=>'status mapping, signature valid/invalid, amount mismatch, duplicate webhook, duplicate order','feature'=>'authorized/unauthorized checkout, paid invoice rejection, pending retry, failed transition','sandbox'=>'test card/payment methods only after credentials configured; never use legacy payment rows','reconciliation'=>'compare gateway status to payment_transactions only','security'=>'secret masking, replay callback, malformed payload, wrong amount, wrong invoice, rate limiting'],'rollout'=>['1'=>'Approve design and install SDK separately','2'=>'Implement service and tests','3'=>'Add sandbox config without production keys','4'=>'Implement checkout/webhook behind feature flag','5'=>'Run sandbox tests','6'=>'Review logs/idempotency/security','7'=>'Only then plan production enablement']];file_put_contents($dir.'/midtrans-implementation-design.json',json_encode($design,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$md="# Midtrans Sandbox Implementation Design\n\nGenerated: {$ts}\n\n## Scope\nDesign only. No package, source code, `.env`, migration, database, data, or gateway transaction was changed.\n\n## Recommended architecture\n\n- Package: `midtrans/midtrans-php` (proposal only).\n- Isolated service: `MidtransGatewayService`.\n- Checkout: `POST /payments/{invoice}/checkout`.\n- Webhook: `POST /payments/midtrans/webhook`.\n- Status: `GET /payments/{transaction}/status`.\n- `gateway_order_id` remains a string and is never reused from legacy data.\n\n## Security and correctness\n\n- Amount is always read from `payment_invoices` server-side.\n- Webhook signature uses SHA-512 and constant-time comparison.\n- Callback processing is idempotent and lock-protected.\n- Legacy `payment` data is never used or modified by the new flow.\n- Secrets are environment-only and never logged.\n- Sandbox and production keys/endpoints are strictly separated.\n\n## Status mapping\n\n`capture/settlement -> paid`, `pending/authorize -> pending`, `deny/cancel/expire/failure/refund/chargeback -> failed`.\n\n## Rollout\n\nImplement service and tests first, configure sandbox separately, test checkout/webhook/idempotency, then review security before any production enablement.\n";file_put_contents($dir.'/midtrans-implementation-design.md',$md);echo $dir,PHP_EOL;
